const LINE_BREAK = /\r\n|\n|\r/;
const SENTENCE_END = new Set(['。', '！', '？', '!', '?']);
const BREAK_GRAPHEMES = new Set(['\r\n', '\n', '\r']);

const IS_WHITE_SPACE = /^\p{White_Space}/u;
const IS_HIRAGANA = /^\p{Script=Hiragana}/u;
