  'katakana',
  'han',
  'asciiLetter',
  'fullwidthLetter',
  'asciiDigit',
  'fullwidthDigit',
  'touten',
  'kuten',
  'fullwidthComma',
  'fullwidthPeriod',
  'whiteSpace',
  'other',
