const PUNCTUATION_LABELS = { touten: '、', kuten: '。', fullwidthComma: '，', fullwidthPeriod: '．' };

function language() {
  let lang = 'en';
  if (typeof obsidian.getLanguage === 'function') {
    lang = obsidian.getLanguage();
  } else if (obsidian.moment && typeof obsidian.moment.locale === 'function') {
    lang = obsidian.moment.locale();
  }
  return typeof lang === 'string' && lang.toLowerCase().startsWith('ja') ? 'ja' : 'en';
}

function fill(template, ...values) {
  return template.replace(/\{(\d)\}/g, (m, i) => (values[Number(i)] === undefined ? m : String(values[Number(i)])));
}

function format(lang, n) {
  return n.toLocaleString(lang === 'ja' ? 'ja-JP' : 'en-US');
}

// Counts summed over the given pieces of text (each selection is counted on its own).
function countPieces(pieces) {
  const total = countText('');
  for (const piece of pieces) {
    const c = countText(piece);
    total.graphemes += c.graphemes;
    total.graphemesWithoutBreaks += c.graphemesWithoutBreaks;
    total.graphemesWithoutWhiteSpace += c.graphemesWithoutWhiteSpace;
    total.lines += c.lines;
    total.sentences += c.sentences;
    if (c.longestSentence > total.longestSentence) {
      total.longestSentence = c.longestSentence;
    }
    for (const k of KINDS) {
      total.kinds[k] += c.kinds[k];
    }
  }
  return total;
}

function before(a, b) {
  return a.line < b.line || (a.line === b.line && a.ch <= b.ch);
}

// The text of each non-empty selection of an Obsidian editor.
function selectedTexts(editor) {
  const out = [];
  for (const sel of editor.listSelections()) {
    const from = before(sel.anchor, sel.head) ? sel.anchor : sel.head;
    const to = from === sel.anchor ? sel.head : sel.anchor;
    if (from.line === to.line && from.ch === to.ch) {
      continue;
    }
    out.push(editor.getRange(from, to));
  }
  return out;
}

function kindLabel(s, k) {
  return PUNCTUATION_LABELS[k] !== undefined ? PUNCTUATION_LABELS[k] : s[k];
}

function detailsText(lang, scope, counts) {
  const s = STRINGS[lang];
  const f = (n) => format(lang, n);
  const lines = [
    scope,
    '',
    `${s.graphemes}: ${f(counts.graphemes)}`,
    `${s.withoutBreaks}: ${f(counts.graphemesWithoutBreaks)}`,
    `${s.withoutWhiteSpace}: ${f(counts.graphemesWithoutWhiteSpace)}`,
    `${s.lines}: ${f(counts.lines)}`,
    `${s.sentences}: ${f(counts.sentences)}`,
    `${s.longest}: ${f(counts.longestSentence)}`,
    '',
    s.byKind,
  ];
  for (const k of KINDS) {
    lines.push(`  ${kindLabel(s, k)}: ${f(counts.kinds[k])}`);
  }
  lines.push('', s.howTitle);
  for (const h of s.how) {
    lines.push(`- ${h}`);
  }
  return lines.join('\n');
}

class BreakdownModal extends obsidian.Modal {
  constructor(app, title, text) {
    super(app);
    this.breakdownTitle = title;
    this.breakdownText = text;
  }

  onOpen() {
    this.titleEl.setText(this.breakdownTitle);
    // setText writes text content only; nothing from the note is read as HTML.
    this.contentEl.createEl('pre', { cls: 'jp-text-breakdown' }).setText(this.breakdownText);
  }

  onClose() {
    this.contentEl.empty();
  }
}

class JapaneseTextBreakdownPlugin extends obsidian.Plugin {
  onload() {
    this.lang = language();
    this.timer = undefined;
    this.item = this.addStatusBarItem();
    this.item.addClass('mod-clickable');
    this.item.setAttribute('aria-label', STRINGS[this.lang].statusTooltip);
    this.registerDomEvent(this.item, 'click', () => this.showBreakdown());

    const schedule = () => this.schedule();
    this.registerEvent(this.app.workspace.on('editor-change', schedule));
    this.registerEvent(this.app.workspace.on('active-leaf-change', schedule));
    this.registerEvent(this.app.workspace.on('file-open', schedule));
    // Obsidian has no selection event; the document's selectionchange is the signal (debounced).
    this.registerDomEvent(document, 'selectionchange', schedule);
    this.register(() => {
      if (this.timer !== undefined) {
        clearTimeout(this.timer);
        this.timer = undefined;
      }
    });

    this.addCommand({
      id: 'show-breakdown',
      name: STRINGS[this.lang].command,
      callback: () => this.showBreakdown(),
    });

    this.app.workspace.onLayoutReady(() => this.updateNow());
  }

  activeEditor() {
    const view = this.app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    return view ? { view, editor: view.editor } : null;
  }

  // Selections count only in the editing view; in reading view the editor keeps an earlier selection that the
  // reader no longer sees, so none is used.
  selections(active) {
    if (typeof active.view.getMode === 'function' && active.view.getMode() === 'preview') {
      return [];
    }
    return selectedTexts(active.editor);
  }

  schedule() {
    if (this.timer !== undefined) {
      clearTimeout(this.timer);
    }
    this.timer = setTimeout(() => this.updateNow(), DEBOUNCE_MS);
  }

  updateNow() {
    this.timer = undefined;
    const s = STRINGS[this.lang];
    const active = this.activeEditor();
    if (!active) {
      this.item.setText('');
      this.item.hide();
      return;
    }
    const text = active.editor.getValue();
    if (text.length > STATUS_LIMIT) {
      this.item.setText(s.statusLarge);
      this.item.show();
      return;
    }
    const all = countText(text).graphemes;
    const selected = this.selections(active);
    if (selected.length > 0) {
      const sel = countPieces(selected).graphemes;
      this.item.setText(fill(s.statusSelection, format(this.lang, sel), format(this.lang, all)));
    } else {
      this.item.setText(fill(s.statusAll, format(this.lang, all)));
    }
    this.item.show();
  }

  showBreakdown() {
    const s = STRINGS[this.lang];
    const active = this.activeEditor();
    if (!active) {
      new obsidian.Notice(s.noEditor);
      return;
    }
    const name = active.view.file ? active.view.file.name : '';
    const selected = this.selections(active);
    const scope = selected.length > 0
      ? fill(s.scopeSelection, format(this.lang, selected.length), name)
      : fill(s.scopeWhole, name);
    const counts = selected.length > 0 ? countPieces(selected) : countText(active.editor.getValue());
    new BreakdownModal(this.app, s.title, detailsText(this.lang, scope, counts)).open();
  }
}

module.exports = JapaneseTextBreakdownPlugin;
